CREATE   VIEW [RegsBI].[vwPanel_CE]
AS
SELECT 
	  [Rics_panelId] AS [apuk_panelid]
	, [apuk_tribunalvenue]
	, [apuk_tribunalmember]
	, [apuk_tribunallegalassessor]
	, [apuk_tribunallaymember]
	, [apuk_tribunalchair]
	, [statuscode]
	, [statecode]
	, [overriddencreatedon]
	, [apuk_paneltype]
	, [owningbusinessunit]
	, [ownerid]
	, [Rics_name] AS [apuk_name]
	, [Modified_On] AS [modifiedon]
	, [ModifiedByName]
	, [Rics_Date] AS [apuk_date]
	, [Created_On] AS [createdon]
	, [CreatedByName]
	, [rics_venueid] AS [apuk_assessmentvenue]
	, [rics_venueidName] AS [apuk_assessmentevent]
FROM [synapse_ce].[vwRics_Panel]
